 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) != 2:
        return out

    def neighborhood_count(pos):
        r0, c0 = pos
        return sum(
            1
            for r, row in enumerate(grid)
            for c, value in enumerate(row)
            if value != 0 and value != 5 and (r, c) != pos
        )

    source, target = sorted(markers, key=neighborhood_count, reverse=True)
    dr, dc = target[0] - source[0], target[1] - source[1]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0 and value != 5:
                rr, cc = r + dr, c + dc
